base.service.py:
def account_summary(account):
    """Return the balance field for the account."""
    return {"balance": account.balance}

base.client.py:
def show_summary(api, account_id):
    """Fetch and display an account summary."""
    return api.get_summary(account_id)["balance"]

review.service.py:
def account_summary(account):
    """Return the balance_cents field for the account."""
    return {"balance_cents": account.balance}

review.client.py:
def show_summary(api, account_id):
    """Fetch and display an account summary."""
    return api.get_summary(account_id)["balance"]
